//! 🧪️ Real config genesis retains its actual native semantic issuer through handoff and cancellation.
use super::EnergyConfigGenesis;
use semio_plugin_ownership::original_store_genesis::{OriginalStoreBirth,OriginalStoreGenesis,OriginalStoreSlot};
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ToValue};
use std::mem::size_of;
const TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(9812),Generation(4),RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<29,maximum_release_bytes:1<<29,maximum_depth:4096},default_now_us,u64::MAX,1<<30)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,f:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,decoder,f));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"config original source physical receipt {p:?}; failure {:?}",result.as_ref().err());result.unwrap()}
#[test]fn original_energy_config_genesis_preserves_reference_defaults_and_native_semantic_authority(){
 type Birth=OriginalStoreGenesis<EnergyConfigGenesis>;
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for stage in [None,Some(0),Some(3),Some(6)]{let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=semio_os_kernel::ActorId("energy-config-reader".into());let mut frame=OriginalStoreBirth::default();let mut slot=None;for index in 0..1048576{let _=turn(&mut caller,&mut decoder,|cx|Birth::admit("energy-config",&actor,cx,&mut frame,&mut slot));if slot.is_some(){break}assert!(index<1048575,"actual Energy config genesis birth did not complete");}let mut birth=slot.unwrap();let mut result=None;let mut foreign=OriginalJobDecodeOwner::empty();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut foreign,|cx|birth.step(cx)));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  for index in 0..1048576{if stage.is_some_and(|stage|birth.progress().0==stage){caller.cancel().cancel_now();break}result=turn(&mut caller,&mut decoder,|cx|birth.step(cx));if result.is_some(){break}assert!(index<1048575,"actual Energy config genesis retained its original stage {:?}",birth.progress());}
  let mut store=result.map(|(address,store)|{assert_eq!(address,"energy-config");turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|{let d=semio_framework_value::RetirementDemand{copy_bytes:size_of::<String>(),release_bytes:address.capacity(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{drop(address);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})}));let snapshot=store.snapshot_ref();let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&snapshot.to_value())).unwrap();assert_eq!(actual,law["default"]);let owners=&store.parts_ref().owners;assert_eq!(std::sync::Arc::as_ptr(owners.one_item_preparation_factory.as_ref().unwrap())as*const(),std::sync::Arc::as_ptr(owners.replay_preparation_factory.as_ref().unwrap())as*const());assert_eq!(store.envelope().history_shape,semio_os_kernel::HistoryShape::Config);OriginalStoreSlot::from_original(store)});
  for index in 0..1048576{if birth.terminal_is_empty(){break}turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|birth.close_step(cx)));assert!(index<1048575);}
  turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|{let d=Birth::boxed_release_demands();close_original_retained_step(cx,d,|_|{drop(birth);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})}));
  for index in 0..1048576{if frame.terminal_is_empty(){break}turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|frame.close_step(cx)));assert!(index<1048575);}
  if let Some(store)=store.as_mut(){for index in 0..1048576{if store.terminal_is_empty(){break}turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|store.close_step(cx)));assert!(index<1048575);}}
  while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(TURN);
 }
}
